// DEVDESK-629 step 8 (F2, F4), RED phase: everything the tests of this step need
// that the production code does not have yet. The file exists so the package
// compiles and the tests fail on an ASSERTION; the bodies below are placeholders
// with the behavior of the code before the step (nothing is ever marked).
//
// The GREEN phase turns this file into nothing:
//   - nexusRole, its constants, memberRole, mayOmit and noResultMark move to
//     production (registry_browser.go, browser_summary.go) and are deleted here;
//   - isNexusGroupOrMember is the rename of listsCacheOnly: delete the wrapper;
//   - the four seams below stay as one-liners over the new fields, or are inlined:
//     entryRole(e) is e.role, withRole(e, r) sets it, classesOf reads
//     searchSummary.MayOmit, withMayOmit sets it, summarize is summarizeSearch
//     with its last argument now a func(string) nexusRole.

// nexusRole is what a picker entry is in a Nexus group.
type nexusRole int

const (
	nexusRoleUnknown nexusRole = iota
	nexusRoleGroup
	nexusRoleProxy
	nexusRoleHosted
)

// noResultMark follows a name on the May omit images line when that registry
// answered with no result.
const noResultMark = " (no result)"

// memberRole maps the repository type the manager reported to a role.
func memberRole(string) nexusRole { return nexusRoleUnknown }

// mayOmit says whether a registry in role, with this outcome, is mentioned on the
// May omit images line.
func mayOmit(nexusRole, imagesearch.Outcome) bool { return false }

// isNexusGroupOrMember is listsCacheOnly under its new name.
func isNexusGroupOrMember(reg config.RegistryItem, bySlug map[string]config.RegistryItem) bool {
	return listsCacheOnly(reg, bySlug)
}

// entryRole is the role of a picker entry (field role).
func entryRole(browserRegistryEntry) nexusRole { return nexusRoleUnknown }

// withRole returns e with its role set.
func withRole(e browserRegistryEntry, _ nexusRole) browserRegistryEntry { return e }

// summaryClasses is a searchSummary read class by class, with the names exactly as
// the summary holds them (no abbreviation).
type summaryClasses struct {
	Pending     int
	Interrupted []string
	Failed      []string
	Refused     []string
	Partial     []string
	MayOmit     []string
	NoResult    []string
	Skipped     []string
}

// classesOf reads a searchSummary (MayOmit is the field that replaces CachedOnly).
func classesOf(s searchSummary) summaryClasses {
	return summaryClasses{
		Pending: s.Pending, Interrupted: s.Interrupted, Failed: s.Failed, Refused: s.Refused,
		Partial: s.Partial, NoResult: s.NoResult, Skipped: s.Skipped,
	}
}

// withMayOmit returns s with its May omit images class set.
func withMayOmit(s searchSummary, _ ...string) searchSummary { return s }

// summarize is summarizeSearch with the role of each key instead of a predicate.
func summarize(keys []string, outcomes map[string]imagesearch.Outcome, live bool,
	label func(string) string, _ func(string) nexusRole) searchSummary {
	return summarizeSearch(keys, outcomes, live, label, func(string) bool { return false })
}
