// browserRegistryEntry is one selectable registry in the browser form.
// Group members have ParentSlug set; standalone registries have it empty.
type browserRegistryEntry struct {
	URL   string
	Alias string
	// repoPrefix goes in front of the repository name. With URL it forms the
	// entry's address, and both the browse path and the pull reference derive
	// from that one pair — which is what stops them meaning two different
	// repositories (D39, §3.18).
	repoPrefix string
	// Slug identifies the entry: its own for a standalone registry, its group's
	// for a member. It is what the result filter resolves labels through, and
	// what replaced matching on URL — two registries configured with the same
	// URL used to collide.
	Slug string
	// cachedOnly marks an entry whose content can only be listed from the
	// discovered-members cache: a Nexus group, its members, or an entry that
	// declares a Nexus group as its parent (DEVDESK-308).
	cachedOnly bool
	// catalogUnderPrefix marks an entry whose catalog Nexus serves under its
	// prefix, at /v2/<prefix>/_catalog: a prefixed member of a Nexus group,
	// discovered or declared (DEVDESK-579).
	catalogUnderPrefix bool
	ParentAlias        string // non-empty = member of a group
	ParentSlug         string
	parentURL          string // URL of the parent RegistryItem (for credential lookup)
	// key identifies the entry among all the others, and is what the checkbox,
	// the remembered exclusions and every result are keyed on (D40). It is not
	// the URL: two registries may be declared on one host — the form enforces
	// slug uniqueness, not URL uniqueness — and §3.18 makes that the ordinary
	// case, since a member is now a bare host plus a prefix. Nor is it Slug,
	// which holds the *group's* slug for a member and would give a whole group
	// one checkbox. So: the slug for a standalone registry, and the group's slug
		registries:   registries,
		width:        width,
		height:       height,
		repoInput:    repoInput,
		selectedRegs: make(map[string]bool),
		focusedField: brFieldRepo,
		filterInput:  fi,
		tagTable:     *newTagTable(),
		searcher:     defaultImageSearcher,
		searchTable:  *newSearchTable(),
		scanCache:    make(map[string]cache.ImageScanEntry),
		state:        browserStateInput,
	}
	b.buildEntries(groups, deselected)
	b.resizeInputs()
	b.resizeTables()
	b.updateFocus()
	return b
}

// buildEntries expands every configured registry into the lines the picker
// shows: a group into its cached members under a header, anything else into
// itself.
//
// A selection is remembered as the entries that were *un*checked, so a member
// discovered since the last visit arrives checked like every other new one.
func (b *RegistryBrowser) buildEntries(groups map[string]cache.RegistryGroupEntry, deselected map[string]bool) {
	b.entries = nil
	b.rows = nil
	bySlug := make(map[string]config.RegistryItem, len(b.registries))
	for _, reg := range b.registries {
		bySlug[reg.Slug] = reg
	}
	for _, reg := range b.registries {
		alias := browserAlias(reg)
		// Members share their group's host and therefore its single credential
		// entry, so they share the decision the group made about using it.
		mode := config.ResolveAuthMode(reg, nil)

		members := groups[reg.Slug].Members
		cacheOnly := listsCacheOnly(reg, bySlug)
		if reg.Kind != config.KindGroup || len(members) == 0 {
			// A group nobody has discovered yet is offered as itself: it is a
			// pullable registry too, and hiding it would be worse than listing
			// it without the members it may have.
			b.rows = append(b.rows, pickerRow{label: alias, entry: len(b.entries)})
			b.entries = append(b.entries, browserRegistryEntry{
				URL: reg.URL, Alias: alias, Slug: reg.Slug, authMode: mode,
				repoPrefix: reg.RepoPrefix,
				key:        reg.Slug,
				cachedOnly: cacheOnly,
				// The same predicate, narrowed to the entries that have a prefix. It
				// is not the discovered members' (IsNexusGroup && RepoPrefix != ""):
				// the two coincide because checkRepoPrefixes refuses a repo_prefix on
				// a group, so no entry here is a group with a prefix. Do not "fix" the
				// asymmetry.
				catalogUnderPrefix: cacheOnly && reg.RepoPrefix != "",
			})
			continue
		}

		b.rows = append(b.rows, pickerRow{groupSlug: reg.Slug, label: alias, entry: -1})
		for _, m := range members {
			b.rows = append(b.rows, pickerRow{label: "  " + m.Alias, entry: len(b.entries)})
			b.entries = append(b.entries, browserRegistryEntry{
				URL:         m.URL,
				Alias:       m.Alias,
				repoPrefix:  m.RepoPrefix,
				Slug:        reg.Slug,
				ParentAlias: alias,
				ParentSlug:  reg.Slug,
				parentURL:   reg.URL,
				authMode:    mode,
				cachedOnly:  config.IsNexusGroup(reg),
				// Nexus serves a member's catalog under its prefix.
				catalogUnderPrefix: config.IsNexusGroup(reg) && m.RepoPrefix != "",
				key:                memberKey(reg.Slug, m.URL, m.RepoPrefix),
			})
		}
	}

	b.selectedRegs = make(map[string]bool, len(b.entries))
	for _, e := range b.entries {
		b.selectedRegs[e.key] = !deselected[e.key]
	}
}

// listsCacheOnly reports whether reg can only be listed from the cache: it is a
// Nexus group, or it declares a Nexus group as its parent (Q-B ii).
func listsCacheOnly(reg config.RegistryItem, bySlug map[string]config.RegistryItem) bool {
	if config.IsNexusGroup(reg) {
		return true
	}
	return reg.Parent != "" && config.IsNexusGroup(bySlug[reg.Parent])
}

// declaredMembers counts the config entries declared by hand as members of the
// group slug (their Parent is that slug).
func declaredMembers(registries []config.RegistryItem, slug string) int {
	n := 0
	for _, reg := range registries {
		if reg.Parent == slug {
			n++
		}
	}
	return n
}

// memberKey names one member of a group. Scoping it by the group's slug is what
// keeps two groups fronting the same repository apart, and what keeps a member
// from colliding with a standalone registry keyed on its own slug.
//
// The URL alone will not do: every member of a path-routed group answers to the
// same host now, and the prefix is the whole of what tells them apart (§3.18).
func memberKey(groupSlug, memberURL, repoPrefix string) string {
	return groupSlug + "/" + memberURL + "/" + repoPrefix
}

// browserAlias returns what a registry is labelled with in the browser.
//
// With no alias it falls back to the entry's *address* rather than its URL: one
// walking it once per member would repeat every name and credit it to the wrong
// member (DEVDESK-579, 3-A). The rule is "same address", not "Nexus": groups maps
// every group's slug to the group, whatever its provider. Everything else is kept
// as it is, in order. Pure: the input is not modified.
func searchUnits(entries []browserRegistryEntry, groups map[string]config.RegistryItem) []browserRegistryEntry {
	var units []browserRegistryEntry
	placed := map[string]bool{}
	for _, e := range entries {
		g, ok := groups[e.ParentSlug]
		if !ok || e.ParentSlug == "" || e.URL != g.URL || e.repoPrefix != g.RepoPrefix {
			units = append(units, e)
			continue
		}
		if !placed[g.Slug] {
			placed[g.Slug] = true
			units = append(units, groupUnit(e, g))
		}
	}
	return units
}

// groupUnit is the entry that searches group g in place of its member first: the
// group's own address and key, read at the root of its catalog, with what the
// members agreed on (credentials, cache-only). ParentSlug stays g's slug, so the
// group-level `r` stop takes its rows; ParentAlias stays empty, so the label is
// the group's, marked by groupUnitSuffix.
func groupUnit(first browserRegistryEntry, g config.RegistryItem) browserRegistryEntry {
	return browserRegistryEntry{
		URL: g.URL, Alias: browserAlias(g) + groupUnitSuffix, repoPrefix: g.RepoPrefix,
		Slug: g.Slug, ParentSlug: g.Slug, parentURL: g.URL,
		authMode: first.authMode, cachedOnly: first.cachedOnly,
		key: g.Slug,
	}
}

// groupsBySlug maps the slug of every configured group to the group.
func (b *RegistryBrowser) groupsBySlug() map[string]config.RegistryItem {
	groups := map[string]config.RegistryItem{}
	for _, reg := range b.registries {
		if reg.Kind == config.KindGroup {
			groups[reg.Slug] = reg
		}
	}
	return groups
}

