// searchSummary is what the level 1 header says about the lot, names in form order.
type searchSummary struct {
	Pending     int      // in the live lot, no answer yet
	Interrupted []string // the lot was abandoned (→) before they answered
	Failed      []string
	Refused     []string
	Partial     []string // ok or no result, cut at a cap
	CachedOnly  []string // Nexus group or member: listed from cached content only (DEVDESK-308)
	NoResult    []string // answered, nothing matches (Skipped excluded)
	Skipped     []string // catalog not walked: query too short
}

// cachedNoResultMark follows a name in the Cached only line when that registry
// answered with no result: with a cache-only list, it means nothing is cached.
const cachedNoResultMark = " (no result)"

// summarizeSearch sorts the lot's keys into classes. Pure; names are label(key),
// in the order of keys. cachedOnly says which keys list cached content only; a
// concerned key that answered ok or with no result goes to CachedOnly (the
// no-result one marked, and not in NoResult), a partial one also to Partial.
func summarizeSearch(keys []string, outcomes map[string]imagesearch.Outcome, live bool,
	label func(key string) string, cachedOnly func(key string) bool) searchSummary {
	var s searchSummary
	for _, k := range keys {
		oc, ok := outcomes[k]
		if !ok {
			if live {
				s.Pending++
			} else {
				s.Interrupted = append(s.Interrupted, label(k))
			}
			continue
		}
		switch oc.Verdict {
		case imagesearch.VerdictFailed:
			s.Failed = append(s.Failed, label(k))
		case imagesearch.VerdictRefused:
			s.Refused = append(s.Refused, label(k))
		case imagesearch.VerdictNoResult:
			if oc.Skipped {
				s.Skipped = append(s.Skipped, label(k))
				continue
			}
			if oc.Partial {
				s.Partial = append(s.Partial, label(k))
			}
			if cachedOnly(k) {
				s.CachedOnly = append(s.CachedOnly, label(k)+cachedNoResultMark)
				continue
			}
			s.NoResult = append(s.NoResult, label(k))
		case imagesearch.VerdictOK:
			if oc.Partial {
				s.Partial = append(s.Partial, label(k))
			}
			if cachedOnly(k) {
				s.CachedOnly = append(s.CachedOnly, label(k))
			}
		}
	}
	return s
}

// searchSummary summarizes the current level 1 lot (live: b.gen == b.searchGen).
func (b *RegistryBrowser) searchSummary() searchSummary {
	return summarizeSearch(b.searchKeys, b.outcomes, b.gen == b.searchGen, b.entryLabel, b.entryCachedOnly)
}

// entryCachedOnly reports whether the entry behind key lists cached content only.
func (b *RegistryBrowser) entryCachedOnly(key string) bool {
	e := b.entryFor(key)
	return e != nil && e.cachedOnly
}

// entryLabel is the Registry column's label for key: entryAlias, else the URL,
// else the key itself.
func (b *RegistryBrowser) entryLabel(key string) string {
	e := b.entryFor(key)
	if e == nil {
		return key
	}
	if a := entryAlias(*e); a != "" {
		return a
	}
	if e.URL != "" {
		return e.URL
	}
	return key
}

// searchHeaderInfo is the level 1 header: the image count, then one line per class
// that has something to say (nothing when every registry answered: only the count).
// Order: Pending or Interrupted, Failed (red), Refused, Partial (orange), Cached only (orange), No result,
// Skipped (grey). Each name list is abbreviated by fitNames to the room the header
// gives a value, so a +N is never lost; Skipped drops its hint first. termWidth 0
// or less means the width is not known yet. At most shortcut.HeaderRows lines.
func searchHeaderInfo(images int, s searchSummary, termWidth int) []shortcut.HeaderInfo {
	type line struct {
		key    string
		names  []string
		count  string // a ready value, instead of names
		suffix string
		style  lipgloss.Style
	}
	warn := theme.HeaderWarnValueStyle()
	var lines []line
	if s.Pending > 0 {
		lines = append(lines, line{key: "Pending", count: fmt.Sprintf("%d", s.Pending), style: theme.HeaderValueStyle})
	}
	lines = append(lines,
		line{key: "Interrupted", names: s.Interrupted, style: warn},
		line{key: "Failed", names: s.Failed, style: theme.SeverityTextStyle("CRITICAL")},
		line{key: "Refused", names: s.Refused, style: warn},
		line{key: "Partial", names: s.Partial, style: warn},
		line{key: "Cached only", names: s.CachedOnly, style: warn},
		line{key: "No result", names: s.NoResult, style: theme.DimStyle},
		line{key: "Skipped", names: s.Skipped, suffix: skippedHint, style: theme.DimStyle},
	)
	var kept []line
	keys := []string{"Images"}
	for _, l := range lines {
		if l.count == "" && len(l.names) == 0 {
			continue
		}
		// The budget is HeaderRows lines: Images plus six classes. Pending and
		// Interrupted exclude each other, which leaves seven classes, and
		// Skipped (last) is the one cut if all the others are present at once.
		// That cannot happen today: Skipped only comes from CatalogSearcher
		// (ErrQueryTooShort), and with defaultImageSearcher = ByRegistry(Hub,
		// Catalog) every non-Hub entry goes through it. So when Skipped is
		// present every Nexus entry is Skipped and Cached only is empty: the
		// two exclude each other, at most seven lines. A dedicated Nexus
		// searcher would break that assumption. A new line (IS-14) must
		// revisit this bound rather than be cut silently.
		if len(kept)+1 >= shortcut.HeaderRows {
			break
		}
		kept = append(kept, l)
		keys = append(keys, l.key)
	}
	room := noWidthLimit
	if termWidth > 0 {
		room = shortcut.HeaderValueWidth(termWidth, keys)
	}
	infos := []shortcut.HeaderInfo{{Key: "Images", Value: fmt.Sprintf("%d", images), Style: theme.HeaderValueStyle}}
	for _, l := range kept {
		v := l.count
		if v == "" {
			v = fitNames(l.names, l.suffix, room)
		}
		infos = append(infos, shortcut.HeaderInfo{Key: l.key, Value: v, Style: l.style})
	}
	return infos

package ociresources

import (
	"fmt"
	"os"
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/imagesearch"
)

// DEVDESK-629 step 8 (F2, F4): the level 1 line `Cached only` is now `May omit
// images`. What it says no longer rests on "the list is limited to the cache" (a
// claim nobody measured on a group) but on what was measured: a Nexus group may
// leave out the names of a member it cannot reach right now, without a word (200,
// fewer names), and a proxy that failed or was refused has told nothing.
//
// The mention follows the ROLE of the entry in its Nexus group (group, proxy,
// hosted, unknown), read from the repository type discovery stored for the member.

// typedMember is a discovered member of a Nexus group with the repository type
// discovery read for it ("" = unknown, as in a cache written before the type).
type typedMember struct{ prefix, typ string }

// typedMembers are members of "nx" the way discovery stores them for a path-routed
// group (the host of the HTTP port plus one prefix each), with their type.
func typedMembers(base string, ms ...typedMember) map[string]cache.RegistryGroupEntry {
	var members []cache.RegistryGroupMember
	for _, m := range ms {
		members = append(members, cache.RegistryGroupMember{Alias: m.prefix, URL: base, RepoPrefix: m.prefix, Type: m.typ})
	}
	return map[string]cache.RegistryGroupEntry{"nx": {Members: members}}
}

// typedConnectorMembers are members of "nx" on a connector of its own: the group's
// URL and no prefix, whatever the member, with their type.
func typedConnectorMembers(base string, ms ...typedMember) map[string]cache.RegistryGroupEntry {
	var members []cache.RegistryGroupMember
	for _, m := range ms {
		members = append(members, cache.RegistryGroupMember{Alias: m.prefix, URL: base, Type: m.typ})
	}
	return map[string]cache.RegistryGroupEntry{"nx": {Members: members}}
}

// typedNexusMembersModel opens the browser on the anonymous group "nx" whose
// discovered members are the given typed prefixes at base.
func typedNexusMembersModel(t *testing.T, base string, ms ...typedMember) Model {
	t.Helper()
	return modelWithGroups(t, []config.RegistryItem{anonymousNexusGroup(base)}, typedMembers(base, ms...))
}

func TestMemberRole(t *testing.T) {
	tests := []struct {
		typ  string
		want nexusRole
	}{
		{"hosted", nexusRoleHosted},
		{"proxy", nexusRoleProxy},
		// A group nested in a group may omit what its own members cannot reach.
		{"group", nexusRoleGroup},
		{"", nexusRoleUnknown},
		{"weird", nexusRoleUnknown},
		{"Proxy", nexusRoleUnknown},
	}
	for _, tt := range tests {
		t.Run(fmt.Sprintf("%q", tt.typ), func(t *testing.T) {
			if got := memberRole(tt.typ); got != tt.want {
				t.Errorf("memberRole(%q) = %v, want %v", tt.typ, got, tt.want)
			}
		})
	}
}

// H4: the rule, role by verdict. A group is mentioned whatever it answered (an
// answer of a group says nothing about what it left out) except when the catalog
// was not walked at all; a proxy only when it failed or was refused; a hosted
// repository never (it holds what it holds); an unknown role never (a cache with
// no type, or a type that could not be read: no mention is better than a false one).
func TestMayOmit(t *testing.T) {
	outcomes := []struct {
		name string
		oc   imagesearch.Outcome
	}{
		{"ok", imagesearch.Outcome{Verdict: imagesearch.VerdictOK}},
		{"ok partial", imagesearch.Outcome{Verdict: imagesearch.VerdictOK, Partial: true}},
		{"no result", imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult}},
		{"failed", imagesearch.Outcome{Verdict: imagesearch.VerdictFailed}},
		{"refused", imagesearch.Outcome{Verdict: imagesearch.VerdictRefused}},
		{"skipped", imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult, Skipped: true}},
	}
	roles := []struct {
		name string
		role nexusRole
		want map[string]bool
	}{
		{"group", nexusRoleGroup, map[string]bool{"ok": true, "ok partial": true, "no result": true, "failed": true, "refused": true}},
		{"proxy", nexusRoleProxy, map[string]bool{"failed": true, "refused": true}},
		{"hosted", nexusRoleHosted, nil},
		{"unknown", nexusRoleUnknown, nil},
	}
	for _, r := range roles {
		for _, o := range outcomes {
			t.Run(r.name+"/"+o.name, func(t *testing.T) {
				if got, want := mayOmit(r.role, o.oc), r.want[o.name]; got != want {
					t.Errorf("mayOmit(%s, %s) = %v, want %v", r.name, o.name, got, want)
				}
			})
		}
	}
}

// The words of the line are gone from the production code: the key, the help text,
// the field, the predicate. A comment that still says "cached only" would keep the
// old reading alive, so the scan covers comments too. It names file and line.
func TestNoCachedOnlyWordingLeft(t *testing.T) {
	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatal(err)
	}
	banned := []string{"Cached only", "cachedOnly", "CachedOnly", "cachedNoResultMark", "listsCacheOnly", "nothing in the cache"}
	scanned := 0
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		scanned++
		src, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		for i, line := range strings.Split(string(src), "\n") {
			for _, w := range banned {
				if strings.Contains(line, w) {
					t.Errorf("%s:%d still says %q: %s", name, i+1, w, strings.TrimSpace(line))
				}
			}
		}
	}
	if scanned < 10 {
		t.Fatalf("scanned %d production files, the scan looks at the wrong directory", scanned)
	}
}

// The help says what the line means, in the words the user settled on, and no
// longer reads "(no result)" as "nothing in the cache".
func TestHelpExplainsMayOmitImages(t *testing.T) {
	const sentence = `May omit images (a Nexus proxy or group may not list images it cannot reach right now; "(no result)" does not mean the image is absent)`
	c := lvl1ImagesModel(t).GetHelpContent()

	var all strings.Builder
	header := ""
	for _, kb := range c.KeyBindings {
		all.WriteString(kb.Key + " " + kb.Description + "\n")
		if kb.Key == "Header (Browser images)" {
			header = kb.Description
		}
	}
	for _, s := range c.Sections {
		all.WriteString(s.Title + " " + s.Body + "\n")
	}
	if !strings.Contains(header, sentence) {
		t.Errorf("the Header (Browser images) help lacks %q:\n%s", sentence, header)
	}
	for _, gone := range []string{"Cached only", "nothing in the cache", "cached content"} {
		if strings.Contains(all.String(), gone) {
			t.Errorf("the help still says %q", gone)
		}
	}
